export SIM_VER_XSIM=2026.1
export GCC_VER_XSIM=9.3.0

# catch pipeline exit status
set -Eeuo pipefail

# resolve compiled library path in xsim.ini
export RDI_DATADIR="/home/raymond/Desktop/amd/${SIM_VER_XSIM}/data"
# compile Verilog/System Verilog design sources
echo "xvlog --incr --relax -L uvm -prj test_memory_interface_vlog.prj"
xvlog --incr --relax -L uvm -prj test_memory_interface_vlog.prj 2>&1 | tee compile.log

# compile VHDL design sources
echo "xvhdl --incr --relax -prj test_memory_interface_vhdl.prj"
xvhdl --incr --relax -prj test_memory_interface_vhdl.prj 2>&1 | tee -a compile.log

